fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // Precompute max substrings to split into
    let max_substrings = (maxsplit as usize) + 1;

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting: return single-element vec with original string
                vec![s]
            } else if s.is_empty() {
                // Empty string returns vec with one empty string
                vec![String::new()]
            } else {
                // Use rsplitn for max_substrings
                // rsplitn returns an iterator over &str slices from right side
                let parts: Vec<String> = s
                    .rsplitn(max_substrings, &sep)
                    .map(|part| part.to_string())
                    // reverse to restore original left-to-right order
                    .collect::<Vec<_>>()
                    .into_iter()
                    .rev()
                    .collect();

                parts
            }
        })
        .collect()
}